const row = $json || {};
const entries = Object.entries(row).filter(([k]) => k !== "logo_url");
const emailRe = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;
let email = "";
for (const [k, v] of entries) {
  if (/e-?mail/i.test(k) && v && emailRe.test(String(v))) { email = String(v); break; }
}
if (!email) { for (const [, v] of entries) { const m = String(v || "").match(emailRe); if (m) { email = m[0]; break; } } }
email = email.toLowerCase().trim();
let name = "";
for (const [k, v] of entries) { if (/full\s*name|your name|name/i.test(k) && v) { name = String(v).trim(); break; } }
if (!name && email) name = email.split("@")[0];
const submission = {};
for (const [k, v] of entries) { submission[String(k).trim()] = (v === null || v === undefined) ? "" : String(v).trim(); }
return [{ json: { student_name: name, student_email: email, logo_url: row.logo_url || "", submitted_at: new Date().toISOString(), submission } }];

const ctx = $("Normalize Submission").first().json;
const email = (ctx.student_email || "").toLowerCase().trim();
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const existing = rows.map(r => String(r.Email || r.email || r["Email Address"] || "").toLowerCase().trim()).filter(Boolean);
let isNew = "yes";
if (!email) isNew = "no";
else if (existing.includes(email)) isNew = "no";
const reason = !email ? "missing_email" : (existing.includes(email) ? "duplicate" : "new");
return [{ json: { ...ctx, is_new: isNew, dedupe_reason: reason, existing_count: existing.length } }];

const ctx = $json;
const sub = ctx.submission || {};
const blob = (ctx.student_name + " " + Object.values(sub).join(" ")).toLowerCase();
let type = "90-day"; let days = 90; let label = "90 Days";
const isPro = (/(experienced|working professional|full[- ]?time employ|years of experience|currently employed)/.test(blob) && !/fresher|student/.test(blob)) || /experienced professional/.test(blob);
if (isPro) { type = "90-day"; days = 90; label = "90 Days"; }
else if (/bba/.test(blob)) {
  if (/(3rd|third|final)\s*year/.test(blob)) { type = "1-year"; days = 365; label = "1 Year"; }
  else if (/(1st|first|2nd|second)\s*year/.test(blob)) { type = "2-year"; days = 730; label = "2 Years"; }
  else { type = "1-year"; days = 365; label = "1 Year"; }
}
else if (/mba/.test(blob)) {
  if (/(2nd|second|final)\s*year/.test(blob)) { type = "90-day"; days = 90; label = "90 Days"; }
  else if (/(1st|first)\s*year/.test(blob)) { type = "2-year"; days = 730; label = "2 Years"; }
  else { type = "90-day"; days = 90; label = "90 Days"; }
}
return [{ json: { ...ctx, roadmap_type: type, roadmap_days: days, roadmap_label: label } }];

const ctx = $("Roadmap Duration").first().json;
let raw = String(($json.text) || ($json.response) || "").trim();
raw = raw.replace(/^```(json)?/i, "").replace(/```$/i, "").trim();
const s = raw.indexOf("{"); const e = raw.lastIndexOf("}");
let ai = null; let valid = "no";
try { if (s !== -1 && e !== -1) { ai = JSON.parse(raw.slice(s, e + 1)); } } catch (err) { ai = null; }
const required = ["student_snapshot","readiness","primary_career","alignment","gap_analysis","ninety_day_plan","resume","compensation"];
if (ai && required.every(k => ai[k])) valid = "yes";
if (valid === "yes" && ai.roadmap) ai.roadmap.duration_label = ctx.roadmap_label;
return [{ json: { valid, ai, student_name: ctx.student_name, student_email: ctx.student_email, roadmap_type: ctx.roadmap_type, roadmap_days: ctx.roadmap_days, roadmap_label: ctx.roadmap_label, logo_url: ctx.logo_url, submission: ctx.submission } }];

const v = $("Validate Intelligence").first().json; const ai = v.ai || {}; const s = ai.student_snapshot || {};
return [{ json: {
  Timestamp: new Date().toISOString(),
  Name: v.student_name || "", Email: v.student_email || "",
  Location: s.location || "", "Current Status": s.current_status || "", "Experience Level": s.experience_level || "",
  "Target Role": (ai.primary_career||{}).role || "", "Target Industry": (ai.target_industry||{}).name || ""
} }];

