  "Target Day": t.target_day != null ? String(t.target_day) : "",
  Status: "NOT STARTED", "Progress %": "0", Notes: t.linked_gap ? ("Linked gap: " + t.linked_gap) : "", "Evidence/Link": ""
} }));

const ai = $("Validate Intelligence").first().json.ai || {};
const skills = ai.skill_plan || [];
return skills.map(s => ({ json: {
