const item = $input.first();
const bin = item.binary || {};
const v = $("Validate Intelligence").first().json; const ai = v.ai || {};
const report = bin.career_report_pdf || {}; const resume = bin.resume_pdf || {};
const pdfOk = (b) => b && (String(b.mimeType||"").indexOf("pdf") !== -1) && (b.fileSize == null || Number(b.fileSize) > 0 || (b.data && b.data.length > 0));
const reportChecks = [ai.student_snapshot, ai.readiness && ai.readiness.dimensions && ai.readiness.dimensions.length, ai.primary_career && ai.primary_career.role, ai.alignment && ai.alignment.score != null, ai.gap_analysis && ai.gap_analysis.length, ai.ninety_day_plan && ai.ninety_day_plan.length, ai.compensation, ai.final_direction];
const reportPass = reportChecks.every(Boolean) && pdfOk(report);
const r = ai.resume || {}; const flat = JSON.stringify(r).toLowerCase();
const banned = ["not provided","not applicable","n/a","unknown","unavailable","to be added","no information"];
const noPlaceholders = !banned.some(b => flat.indexOf(b) !== -1);
const resumeContentOk = !!(r.name && r.title && r.summary && (r.skills||[]).length && (r.education||[]).length);
const resumePass = resumeContentOk && noPlaceholders && pdfOk(resume);
