if (!pdfOk(resume)) notes.push("resume PDF binary invalid");
if (!noPlaceholders) notes.push("resume contains placeholder text");
if (!resumeContentOk) notes.push("resume missing required content");
return [{ json: { quality_pass: pass, quality_notes: notes.join("; ") || "All checks passed" }, binary: item.binary }];

